esc=lambda v:html.escape(str(v))
db=load('opportunities.json'); ops=db['opportunities']; deep=load('top15_analysis.json'); blue=load('launch_blueprints.json'); sources=load('sources.json'); rows=load('financial_summary.json'); full=load('financial_results.json')
