dash='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Income Portfolio Planning Dashboard</title><style>'''+css+'''label{font-size:14px;font-weight:650;margin-right:18px;display:inline-block}select,input{font:inherit;padding:8px 12px;margin:7px 0;border:1px solid #90a7b5;border-radius:5px;background:white;color:#18394e}.controls{display:flex;gap:20px;flex-wrap:wrap}.chart{display:flex;gap:8px;align-items:flex-end;height:180px;padding-top:28px;margin:25px 0 35px}.bar{flex:1;background:#0c889a;position:relative;min-height:3px}.bar label{position:absolute;bottom:-26px;left:0;right:0;text-align:center;margin:0}.bar span{position:absolute;top:-25px;left:0;right:0;text-align:center;font-size:13px}.chart-note{font-size:13px}.negative{color:#ae3b2f}</style></head><body><header><p>Local planning dashboard · no live accounts connected</p></header><main><h1>Portfolio planning console</h1><p class="lead">Compare assumptions, cash timing and workload before committing more money or time.</p><p class="notice warning">All figures are modeled scenarios, not actual sales, balances or monitoring. This file uses embedded local data. It does not send data, call APIs, track visitors, place orders or save changes. Health is unavailable until a real system is connected.</p><p><a href="Automated_Online_Income_Portfolio.html">Read the complete A–J strategy and sources</a></p><h2>Financial scenarios</h2><div class="controls"><label>Scenario<br><select id="scenario"><option value="pessimistic">Pessimistic</option><option value="base" selected>Base</option><option value="optimistic">Optimistic</option></select></label><label>Initial capital CAD<br><select id="budget"><option>0</option><option>100</option><option selected>500</option><option>2000</option></select></label><label>Focus month<br><select id="month"><option>1</option><option>3</option><option>6</option><option selected>12</option><option>24</option></select></label></div><div id="cards" class="metrics"></div><h3>Monthly pretax net at required milestones</h3><div id="chart" class="chart" aria-label="Milestone pretax profit"></div><p class="chart-note">Bars show positive net above zero. Negative results are explicitly labelled; the table is authoritative. Values rounded to CAD.</p><div id="finance"></div><h3>Cash and cumulative return</h3><div id="cash"></div><p>Tax reserve is a planning policy, not calculated tax. Total hours include setup, acquisition, growth and maintenance. Economic profit values all owner time at CAD25/hour. Initial capital is not revenue; payouts are not new sales.</p><section><h2>Ranked opportunity explorer</h2><div class="controls"><label>Search name, category or evidence<br><input id="search" type="search" placeholder="e.g. data, game, subscription"></label><label>View<br><select id="view"><option value="all">All 54 opportunities</option><option value="15">Top 15</option><option value="core">Three staged core concepts</option></select></label></div><p id="count"></p><div id="opps"></div><p>The score is analyst judgement, not a measured chance of success. No-sales/base/upside opportunity nets use simplified conditional unit models; they are separate from the combined cash-flow scenarios above. Do not sum the opportunities.</p></section><section><h2>Operations to connect after validation</h2><p>Revenue, expenses, subscriber counts, conversion, health alerts and actual maintenance hours are currently <strong>unavailable</strong>. The report's section I defines the records, reconciliation and approval boundaries needed for a live system.</p><ul><li>Start with deliberate provider exports and a ledger.</li><li>Add authenticated, read-only integrations only after they save meaningful work.</li><li>Show paid-access failures, stale data and unresolved incidents, rather than a misleading green “healthy” state.</li><li>Keep monthly owner-hours tracking alongside cash profit.</li></ul></section><footer>Research checked 13 October 2026. Scenario and opportunity data are embedded for offline use. Rebuild this dashboard after changing assumptions so it does not show stale results.</footer></main><script>const FINANCE=__FINANCE__;const OPS=__OPS__;const money=n=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:0}).format(n);const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function table(head,rows){return '<div class="tablewrap"><table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}function render(){const scenario=document.getElementById('scenario').value,budget=Number(document.getElementById('budget').value),month=Number(document.getElementById('month').value);const rr=FINANCE.filter(r=>r.scenario===scenario&&r.initial_capital===budget),r=rr.find(r=>r.month===month);const metrics=[['$'+money(r.pretax_profit),'M'+month+' pretax monthly net'],['$'+money(r.economic_profit),'After CAD25/hour owner time'],[r.owner_hours.toFixed(1)+' h','Total owner work this month'],['$'+money(r.cash_end),'Unreserved ordinary cash'],['$'+money(r.tax_reserve_held),'Separate tax reserve cash'],[r.maintenance_hours.toFixed(1)+' h','Maintenance only; subset of total']];document.getElementById('cards').innerHTML=metrics.map(m=>'<div class="metric"><b>'+m[0]+'</b><span>'+m[1]+'</span></div>').join('');const max=Math.max(1,...rr.map(x=>x.pretax_profit));document.getElementById('chart').innerHTML=rr.map(x=>'<div class="bar" style="height:'+Math.max(3,x.pretax_profit/max*140)+'px"><span class="'+(x.pretax_profit<0?'negative':'')+'">$'+money(x.pretax_profit)+'</span><label>M'+x.month+'</label></div>').join('');document.getElementById('finance').innerHTML=table(['Month','Revenue','Expenses','Pretax net','Economic net','Total hours','Maintenance'],rr.map(x=>[x.month,money(x.gross_revenue),money(x.total_expenses),money(x.pretax_profit),money(x.economic_profit),x.owner_hours.toFixed(1),x.maintenance_hours.toFixed(1)]));document.getElementById('cash').innerHTML=table(['Month','Cash','Tax reserve','Receivables','Cum. pretax','Cum. economic','Cum. hours'],rr.map(x=>[x.month,money(x.cash_end),money(x.tax_reserve_held),money(x.receivables_end),money(x.cumulative_pretax_profit),money(x.cumulative_economic_profit),x.cumulative_owner_hours.toFixed(1)]))}function renderOps(){const query=document.getElementById('search').value.toLowerCase(),view=document.getElementById('view').value;const data=OPS.filter(o=>(view==='all'||view==='15'&&o.rank<=15||view==='core'&&['O01','O02','O04'].includes(o.id))&&[o.name,o.category,o.evidence].join(' ').toLowerCase().includes(query));document.getElementById('count').textContent=data.length+' matching opportunities';document.getElementById('opps').innerHTML=table(['Rank / product','Score','Setup h','Maint. h/wk','Net no-sales/base/upside','Evidence / priority'],data.map(o=>[o.rank+'. <a href="Automated_Online_Income_Portfolio.html#'+o.id+'">'+escapeText(o.name)+'</a>',o.weighted_score,o.setup_hours.join('–'),o.weekly_maintenance_hours.join('–'),o.monthly_net_scenarios_cad.map(money).join(' / '),escapeText(o.evidence)+'<br>'+escapeText(o.portfolio_fit)]))}['scenario','budget','month'].forEach(id=>document.getElementById(id).addEventListener('change',render));document.getElementById('search').addEventListener('input',renderOps);document.getElementById('view').addEventListener('change',renderOps);render();renderOps();</script></body></html>'''
dash=dash.replace('__FINANCE__',json.dumps(rows)).replace('__OPS__',json.dumps(minimal))
(P/'Portfolio_Dashboard.html').write_text(dash)
